// CreatePrim's typed attributes, generated by tools/node_attributes.py from node_definitions.usda: its
// inputs and properties, read by name, and its outputs, committed by name. Don't edit it: change the
// definition and run `uv run python tools/node_attributes.py render`.
#pragma once

#include <pxr/base/tf/token.h>
#include <pxr/pxr.h>
#include <pxr/usd/sdf/path.h>

#include <string>

#include "node_input_reader.h"
#include "node_roles.h"

namespace proscenium {

struct CreatePrimInputs {
  static constexpr const char* kParent = "inputs:parent";
  static constexpr const char* kName = "inputs:name";
  static constexpr const char* kSpecifier = "props:specifier";
  static constexpr const char* kType = "props:type";

  PXR_NS::SdfPath parent{};
  std::string name{};
  PXR_NS::TfToken specifier{};
  PXR_NS::TfToken type{};
};

inline CreatePrimInputs ReadCreatePrimInputs(const NodeInputReader& reader) {
  CreatePrimInputs inputs;
  inputs.parent = reader.Prim("inputs:parent");
  inputs.name = reader.Value<std::string>("inputs:name");
  inputs.specifier = reader.Value<PXR_NS::TfToken>("props:specifier");
  inputs.type = reader.Value<PXR_NS::TfToken>("props:type");
  return inputs;
}

// What the node outputs; an output left empty, such as a null layer, commits nothing.
struct CreatePrimOutputs {
  static constexpr const char* kPrim = "outputs:prim";

  PXR_NS::SdfPath prim{};
};

inline ValueOutputs WriteCreatePrimOutputs(const CreatePrimOutputs& outputs) {
  ValueOutputs values;
  if (!outputs.prim.IsEmpty()) {
    values[PXR_NS::TfToken("outputs:prim")] = PXR_NS::VtValue(outputs.prim.GetAsString());
  }
  return values;
}

}  // namespace proscenium
